import{_ as i,c as a,o as t,ag as r}from"./chunks/framework.DfL_BkQ-.js";const g=JSON.parse(`{"title":"Guide d'utilisation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/usage.md","filePath":"fr/guide/usage.md","lastUpdated":1794112334000}`),s={name:"fr/guide/usage.md"};function n(o,e,l,d,u,c){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="guide-d-utilisation" tabindex="-1">Guide d&#39;utilisation <a class="header-anchor" href="#guide-d-utilisation" aria-label="Permalink to &quot;Guide d&#39;utilisation&quot;">​</a></h1><h2 id="navigation-de-base" tabindex="-1">Navigation de base <a class="header-anchor" href="#navigation-de-base" aria-label="Permalink to &quot;Navigation de base&quot;">​</a></h2><h3 id="ouvrir-des-images" tabindex="-1">Ouvrir des images <a class="header-anchor" href="#ouvrir-des-images" aria-label="Permalink to &quot;Ouvrir des images&quot;">​</a></h3><ul><li><strong>Menu Fichier</strong> : cliquez sur Fichier &gt; Ouvrir pour sélectionner des images individuelles</li><li><strong>Vue par dossier</strong> : cliquez sur Fichier &gt; Ouvrir un dossier pour parcourir un répertoire entier</li><li><strong>Glisser-déposer</strong> : faites glisser des fichiers image ou des dossiers directement dans la fenêtre de l&#39;application</li><li><strong>Extension Chrome</strong> : cliquez sur l&#39;icône de l&#39;extension sur n&#39;importe quel site web pour voir toutes les images</li></ul><h2 id="extension-de-synchronisation-finder" tabindex="-1">Extension de synchronisation Finder <a class="header-anchor" href="#extension-de-synchronisation-finder" aria-label="Permalink to &quot;Extension de synchronisation Finder&quot;">​</a></h2><h3 id="traitement-rapide-des-images-depuis-le-finder" tabindex="-1">Traitement rapide des images depuis le Finder <a class="header-anchor" href="#traitement-rapide-des-images-depuis-le-finder" aria-label="Permalink to &quot;Traitement rapide des images depuis le Finder&quot;">​</a></h3><p>L&#39;extension de synchronisation ajoute un bouton Nicasa dans la barre d&#39;outils du Finder pour traiter rapidement les images :</p><ol><li>Sélectionnez une ou plusieurs images dans le Finder</li><li>Cliquez sur le bouton Nicasa de la barre d&#39;outils</li><li>Choisissez <strong>Optimiseur d&#39;images</strong> pour compresser les fichiers ou <strong>Éditeur d&#39;images par IA</strong> pour améliorer les images</li><li>Nicasa s&#39;ouvre automatiquement et traite les fichiers sélectionnés</li></ol><h3 id="formats-pris-en-charge" tabindex="-1">Formats pris en charge <a class="header-anchor" href="#formats-pris-en-charge" aria-label="Permalink to &quot;Formats pris en charge&quot;">​</a></h3><p>L&#39;extension fonctionne avec les fichiers JPG, PNG, GIF, BMP, WebP, SVG, TIFF et ICO.</p><h3 id="vue-miniatures" tabindex="-1">Vue miniatures <a class="header-anchor" href="#vue-miniatures" aria-label="Permalink to &quot;Vue miniatures&quot;">​</a></h3><p>L&#39;interface principale affiche des miniatures de vos images :</p><ul><li><strong>Clic</strong> : sélectionner une image</li><li><strong>Double-clic</strong> : ouvrir en vue complète</li><li><strong>Clic droit</strong> : accéder au menu contextuel avec les options</li></ul><h3 id="mode-d-affichage-complet" tabindex="-1">Mode d&#39;affichage complet <a class="header-anchor" href="#mode-d-affichage-complet" aria-label="Permalink to &quot;Mode d&#39;affichage complet&quot;">​</a></h3><p>Lors de la visualisation d&#39;une image en plein écran :</p><ul><li><strong>Zoom</strong> : utilisez la molette de la souris ou les contrôles de zoom</li><li><strong>Déplacement</strong> : cliquez et faites glisser pour vous déplacer dans les images agrandies</li><li><strong>Navigation</strong> : utilisez les flèches ou les boutons à l&#39;écran pour passer à l&#39;image suivante ou précédente</li></ul><h2 id="fonction-de-capture-d-ecran" tabindex="-1">Fonction de capture d&#39;écran <a class="header-anchor" href="#fonction-de-capture-d-ecran" aria-label="Permalink to &quot;Fonction de capture d&#39;écran&quot;">​</a></h2><h3 id="prendre-des-captures-d-ecran" tabindex="-1">Prendre des captures d&#39;écran <a class="header-anchor" href="#prendre-des-captures-d-ecran" aria-label="Permalink to &quot;Prendre des captures d&#39;écran&quot;">​</a></h3><ol><li>Cliquez sur le bouton de capture dans la barre d&#39;outils ou utilisez le raccourci clavier</li><li>Sélectionnez la zone à capturer</li><li>La capture s&#39;ouvre automatiquement dans Nicasa pour être éditée</li></ol><h3 id="autorisation-d-enregistrement-de-l-ecran" tabindex="-1">Autorisation d&#39;enregistrement de l&#39;écran <a class="header-anchor" href="#autorisation-d-enregistrement-de-l-ecran" aria-label="Permalink to &quot;Autorisation d&#39;enregistrement de l&#39;écran&quot;">​</a></h3><p>Pour la fonction de capture, Nicasa a besoin de l&#39;autorisation d&#39;enregistrement de l&#39;écran :</p><ol><li>Allez dans Réglages Système &gt; Confidentialité et sécurité &gt; Enregistrement de l&#39;écran</li><li>Cochez la case en face de Nicasa</li><li>Redémarrez Nicasa si nécessaire</li></ol><h2 id="editeur-d-images-par-ia" tabindex="-1">Éditeur d&#39;images par IA <a class="header-anchor" href="#editeur-d-images-par-ia" aria-label="Permalink to &quot;Éditeur d&#39;images par IA&quot;">​</a></h2><h3 id="presentation-de-l-editeur-par-ia" tabindex="-1">Présentation de l&#39;éditeur par IA <a class="header-anchor" href="#presentation-de-l-editeur-par-ia" aria-label="Permalink to &quot;Présentation de l&#39;éditeur par IA&quot;">​</a></h3><p>Nicasa inclut de puissants outils d&#39;IA pour améliorer les images :</p><ul><li><strong>Amélioration automatique</strong> : améliore automatiquement la qualité de l&#39;image</li><li><strong>Recadrage intelligent</strong> : suggestions intelligentes de recadrage</li><li><strong>Correction des couleurs</strong> : ajustements de couleur pilotés par l&#39;IA</li><li><strong>Réduction du bruit</strong> : élimine le bruit et le grain</li><li><strong>Netteté</strong> : accentuation intelligente sans artefacts</li></ul><h3 id="outil-de-retouche-inpainting" tabindex="-1">Outil de retouche (inpainting) <a class="header-anchor" href="#outil-de-retouche-inpainting" aria-label="Permalink to &quot;Outil de retouche (inpainting)&quot;">​</a></h3><p>L&#39;outil de retouche vous permet de :</p><ul><li>supprimer des objets indésirables des images</li><li>combler intelligemment les parties manquantes</li><li>restaurer des zones endommagées</li><li>nettoyer les arrière-plans</li></ul><h2 id="mode-superposition-transparente" tabindex="-1">Mode superposition transparente <a class="header-anchor" href="#mode-superposition-transparente" aria-label="Permalink to &quot;Mode superposition transparente&quot;">​</a></h2><p>Parfait pour les designers et les artistes :</p><ol><li>Ouvrez une image dans Nicasa</li><li>Activez le mode superposition depuis le menu Présentation</li><li>Ajustez la transparence avec le curseur</li><li>L&#39;image reste au-dessus de toutes les autres fenêtres</li><li>Utilisez-la pour le décalquage, le travail de référence ou la comparaison d&#39;interfaces</li></ol><h2 id="raccourcis-clavier" tabindex="-1">Raccourcis clavier <a class="header-anchor" href="#raccourcis-clavier" aria-label="Permalink to &quot;Raccourcis clavier&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Raccourci</th><th>Action</th></tr></thead><tbody><tr><td><code>Cmd+O</code></td><td>Ouvrir un fichier</td></tr><tr><td><code>Cmd+Shift+O</code></td><td>Ouvrir un dossier</td></tr><tr><td><code>Space</code></td><td>Image suivante</td></tr><tr><td><code>Shift+Space</code></td><td>Image précédente</td></tr><tr><td><code>Cmd+F</code></td><td>Basculer en plein écran</td></tr><tr><td><code>Cmd+W</code></td><td>Fermer la fenêtre</td></tr><tr><td><code>Cmd+Q</code></td><td>Quitter l&#39;application</td></tr><tr><td><code>Delete</code></td><td>Supprimer l&#39;image courante</td></tr><tr><td><code>Cmd+S</code></td><td>Prendre une capture d&#39;écran</td></tr><tr><td><code>Cmd+E</code></td><td>Ouvrir l&#39;éditeur IA</td></tr><tr><td><code>Cmd+T</code></td><td>Basculer le mode superposition</td></tr></tbody></table><h2 id="integration-de-l-extension-chrome" tabindex="-1">Intégration de l&#39;extension Chrome <a class="header-anchor" href="#integration-de-l-extension-chrome" aria-label="Permalink to &quot;Intégration de l&#39;extension Chrome&quot;">​</a></h2><h3 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h3><ol><li>Installez l&#39;<a href="https://chromewebstore.google.com/detail/nicasa-image-viewer/cihceekeiedkinpjjjfehlgjdhpeokbj" target="_blank" rel="noreferrer">extension Chrome Nicasa</a></li><li>L&#39;icône de l&#39;extension apparaît dans la barre d&#39;outils de votre navigateur</li></ol><h3 id="utilisation" tabindex="-1">Utilisation <a class="header-anchor" href="#utilisation" aria-label="Permalink to &quot;Utilisation&quot;">​</a></h3><ol><li>Visitez n&#39;importe quel site web</li><li>Cliquez sur l&#39;icône de l&#39;extension Nicasa</li><li>Toutes les images de la page s&#39;affichent dans une grille</li><li>Cliquez sur une image pour l&#39;ouvrir dans Nicasa</li><li>Utilisez toutes les fonctionnalités de Nicasa sur les images web</li></ol><h2 id="reglages" tabindex="-1">Réglages <a class="header-anchor" href="#reglages" aria-label="Permalink to &quot;Réglages&quot;">​</a></h2><p>Accédez aux réglages via Nicasa &gt; Préférences :</p><ul><li><strong>Général</strong> : dossier par défaut, langue, thème</li><li><strong>Affichage</strong> : taille des miniatures, comportement du zoom, animations</li><li><strong>Éditeur</strong> : préférences des outils d&#39;IA, améliorations par défaut</li><li><strong>Extensions</strong> : réglages de l&#39;extension Chrome</li><li><strong>Confidentialité</strong> : préférences de collecte de données</li></ul><h2 id="formats-pris-en-charge-1" tabindex="-1">Formats pris en charge <a class="header-anchor" href="#formats-pris-en-charge-1" aria-label="Permalink to &quot;Formats pris en charge&quot;">​</a></h2><p>Nicasa prend en charge tous les formats d&#39;image courants :</p><ul><li><p><strong>Standard</strong> : JPEG, PNG, GIF, BMP, TIFF, WebP</p></li><li><p><strong>RAW</strong> : CR2, NEF, ARW, DNG (avec conversion)</p></li><li><p><strong>Vectoriel</strong> : SVG (avec rastérisation)</p></li><li><p><strong>Animés</strong> : GIF, APNG</p></li><li><p>JPEG/JPG</p></li><li><p>PNG</p></li><li><p>GIF (statique)</p></li><li><p>BMP</p></li><li><p>TIFF</p></li><li><p>WebP</p></li><li><p>HEIC (sur les systèmes compatibles)</p></li></ul><h2 id="astuces-et-conseils" tabindex="-1">Astuces et conseils <a class="header-anchor" href="#astuces-et-conseils" aria-label="Permalink to &quot;Astuces et conseils&quot;">​</a></h2><ul><li>Utilisez la barre de recherche pour trouver rapidement des images par nom de fichier</li><li>Créez des collections en organisant vos images dans des dossiers</li><li>Utilisez le système de notation pour marquer vos images favorites</li><li>Exportez vos images dans différents formats depuis le menu Fichier</li></ul>',47)])])}const m=i(s,[["render",n]]);export{g as __pageData,m as default};
